"""Build dark_mode.svg / light_mode.svg: a neofetch-style profile card with an
ASCII portrait generated from assets/avatar.png. Original code for PauGon75."""
import html, sys
from pathlib import Path
import json

ROOT = Path(__file__).resolve().parent.parent
COLS = 52
PANEL = 64            # width of the info panel in characters
CW, LH, FS = 8.4, 15.0, 14   # char width, line height, font size

# ---------- ASCII portrait (pre-generated by make_portrait.py) ----------
def portrait(invert):
    f = ROOT/("assets/ascii-light.txt" if invert else "assets/ascii-dark.txt")
    return f.read_text(encoding="utf-8").split("\n")

# ---------- info panel ----------
def row(key, val, width=PANEL):
    dots = width - len(key) - len(val) - 2
    assert dots >= 2, (key, val, dots)
    return ("kv", key, "."*dots, val)

def rule(label, width=PANEL):
    t = f"- {label} "
    return ("rule", t + "-"*(width-len(t)))

STATS = json.loads((ROOT/"cache/stats.json").read_text()) if (ROOT/"cache/stats.json").exists() else {}

INFO = [
 ("rule","pau@citm " + "-"*(PANEL-9)),
 row("Role","Gameplay Programmer & Tech Designer"),
 row("Education","CITM-UPC, Barcelona (2023-2027)"),
 row("Studio","Forbidden Candy (Thornetica, Godot)"),
 row("Languages","C++, C#, C, GDScript, Python, x86 ASM"),
 row("Engines","Unity, Godot, Unreal Engine 5, custom C++/OpenGL"),
 row("Tools","Git, CMake, Jira"),
 row("Focus","Performance optimization, real-time 3D"),
 row("Hobbies.Software","Simulations, game engines"),
 ("blank",),
 rule("Highlights"),
 row("Fable of the Eclipse","Best Student Project nominee, SAGA BCN"),
 row("Thornetica","Steam demo live, 11 levels designed"),
 ("blank",),
 rule("GitHub"),
 row("Followers", str(STATS.get("followers","-"))),
 row("Public contributions (12 mo)", str(STATS.get("contributions","-"))),
 ("blank",),
 rule("Contact"),
 row("LinkedIn","linkedin.com/in/paugonzalezcayuela"),
 row("Portfolio","paugon75.github.io/PauGon75"),
 row("itch.io","paugonzalez.itch.io"),
]

THEMES = {
 "dark":  dict(bg="#0d1117", art="#c9d1d9", key="#ffa657", val="#c9d1d9", dot="#484f58", rule="#79c0ff", invert=False),
 "light": dict(bg="#ffffff", art="#24292f", key="#953800", val="#24292f", dot="#8c959f", rule="#0550ae", invert=True),
}

def build(name, t):
    art = portrait(t["invert"])
    pad = 18
    gap = 3          # chars between art and info
    info_x = pad + COLS*CW + gap*CW
    W = int(info_x + PANEL*CW + pad)
    H = int(pad*2 + max(len(art), len(INFO))*LH)
    top_info = pad + (len(art)-len(INFO))*LH/2
    o = [f'<svg xmlns="http://www.w3.org/2000/svg" width="{W}" height="{H}" viewBox="0 0 {W} {H}" font-family="Consolas, \'DejaVu Sans Mono\', \'Courier New\', monospace" font-size="{FS}">',
         f'<rect width="{W}" height="{H}" rx="10" fill="{t["bg"]}"/>']
    for i,l in enumerate(art):
        o.append(f'<text x="{pad}" y="{pad+(i+1)*LH:.1f}" fill="{t["art"]}" xml:space="preserve" textLength="{COLS*CW:.1f}" lengthAdjust="spacing">{html.escape(l)}</text>')
    for i,r in enumerate(INFO):
        y = top_info + (i+1)*LH
        if r[0]=="kv":
            _,k,d,v = r
            o.append(f'<text x="{info_x:.1f}" y="{y:.1f}" xml:space="preserve"><tspan fill="{t["key"]}">{html.escape(k)}</tspan><tspan fill="{t["dot"]}"> {d} </tspan><tspan fill="{t["val"]}">{html.escape(v)}</tspan></text>')
        elif r[0]=="rule":
            o.append(f'<text x="{info_x:.1f}" y="{y:.1f}" fill="{t["rule"]}" xml:space="preserve">{html.escape(r[1])}</text>')
    o.append('</svg>')
    (ROOT/f"{name}_mode.svg").write_text("\n".join(o), encoding="utf-8")

for n,t in THEMES.items(): build(n,t)
print("ok")
